+/** The language an Accept-Language header asks for (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [tag, ...rest] = part.trim().split(";");
+    const lang = tag.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const p of rest) {
+      const [k, v] = p.split("=").map((x) => x.trim());
+      if (k.toLowerCase() === "q") q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(v ?? "") ? Number(v) : NaN;
+    }
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
